#pragma once

#include <pnes/video.hpp>
#include "../../chr/chr.h"     // CHR tile indices, generated by blobman

// The nametable windows the HUD and menus are drawn into.
namespace windows {
    constexpr u16 kTileBytes = 16;

    inline constexpr ppu::ChrWindow dynamicLevelTiles{
        blob::dynamicLevelTiles::__lma / kTileBytes, 0x00};

    inline constexpr ppu::ChrWindow staticLevelTiles{
        blob::staticLevelTiles::__lma / kTileBytes, 0x40};

    inline constexpr ppu::ChrWindow ui{
        blob::ui::__lma / kTileBytes, 0x40};

    inline constexpr ppu::ChrWindow normalSprites{
        blob::normalSprites::__lma / kTileBytes, 0x00};

    inline constexpr ppu::ChrWindow uiSprites{
        blob::ui::__lma / kTileBytes, 0x80};
}
